<?php declare(strict_types=1);
namespace FMonitor2\PilotHttp;
final class ProductionPrepareFormRenderer implements PrepareFormRenderer,CompatibilityPrepareFormRenderer
{
    public function render(HttpUser $user,array $f):string
    {
        $e=[PilotView::class,'e'];$id=$e($f['id']);$installers='';
        if($f['installers']===[])$installers='<div class="shlz-empty-state"><p>Нет монтажников, допустимых для планового периода объекта.</p></div>';
        else foreach($f['installers']as$x){$busy=$x['busyUntil']===null?'':' · занят до '.$e($x['busyUntil']);$installers.='<div class="fm2-person"><label class="shlz-choice"><input class="shlz-checkbox" type="checkbox" name="installerTabIds[]" value="'.$e($x['tabId']).'">'.$e($x['fio']).' · табельный № '.$e($x['tabId']).' · '.$e($x['position']).'</label><small>'.$e(\str_pad((string)$x['tabId'],5,'0',STR_PAD_LEFT)).' · Трудоустроен'.$busy.'</small></div>';}
        $engineers='';if($f['engineers']===[])$engineers='<div class="shlz-empty-state"><p>Нет доступных инженеров строительного контроля.</p></div>';else foreach($f['engineers']as$x)$engineers.='<div class="fm2-person"><label class="shlz-choice"><input class="shlz-radio" type="radio" name="controlEngineerUserId" value="'.$e($x['userId']).'"'.($x['prefilled']?' checked':'').'>'.$e($x['fio']).' · '.$e($x['position']).'</label>'.($x['prefilled']?'<small>Предложено по объекту</small>':'').'</div>';
        $source=$f['installers']===[]?'':'<div class="fm2-provenance"><p>Источник кадровых данных: '.$e($f['installers'][0]['source']).'</p><p>Актуально на: '.$e($f['installers'][0]['updatedAt']).'</p><p>Bitrix24 / 1С ЗУП · '.$e(\str_replace('T',' ',\substr($f['installers'][0]['updatedAt'],0,16))).' +03:00</p></div>';$route='/pilot/objects/'.$id.'/assignment-order/prepare';
        $summary=PilotView::dl([['Регистрационный номер',$e($f['registrationNumber'])],['Адрес',$e($f['address'])],['Подъезд',$e($f['entrance'])],['Плановое начало',$e($f['plannedStartDate'])],['Плановое окончание',$e($f['plannedFinishDate'])]]);
        $command=isset($f['csrfToken']);$confirmation=$f['installers']!==[]&&$f['engineers']!==[]?'<label class="shlz-choice"><input class="shlz-checkbox" type="checkbox" name="controlEngineerConfirmed" value="yes">Подтверждаю выбор инженера строительного контроля</label>':'';$flash=$f['flash']??null;$notice=$flash?'<div class="fm2-alert" role="status"><a href="#'.($e($flash['field']??'form-errors')).'">'.$e($flash['message']).'</a></div>':'';$hidden=$command?'<input type="hidden" name="csrfToken" value="'.$e($f['csrfToken']).'"><input type="hidden" name="processRevision" value="'.$e($f['processRevision']).'">':'';$submit=$command&&$f['installers']!==[]&&$f['engineers']!==[]?'<button class="shlz-button fm2-submit" type="submit">Сформировать распоряжение</button>':'';$body='<div class="fm2-page-header"><h1>Состав распоряжения</h1></div>'.$summary.'<p>Выберите состав. Распоряжение будет сформировано только после отдельного подтверждения.</p>'.$notice.'<form id="form-errors" class="fm2-form" method="'.($command?'post':'get').'" action="'.$route.'">'.$hidden.'<h2 id="installers">1. Монтажники</h2>'.$source.'<fieldset><legend>Монтажники</legend>'.$installers.'</fieldset><h2 id="engineer">2. Инженер строительного контроля</h2><fieldset><legend>Инженер строительного контроля</legend>'.$engineers.'</fieldset><div id="confirmation">'.$confirmation.'</div>'.$submit.'</form><p><a class="shlz-link" href="/pilot/objects/'.$id.'">Вернуться к объекту монтажа</a></p>';
        $selected=$f['selected']??[];foreach($selected['installers']??[] as$tab)$body=\str_replace('name="installerTabIds[]" value="'.$e($tab).'"','name="installerTabIds[]" value="'.$e($tab).'" checked',$body);if(isset($selected['engineer'])){$body=\preg_replace('/(name="controlEngineerUserId" value="[^"]+") checked/','$1',$body)??$body;$body=\str_replace('name="controlEngineerUserId" value="'.$e($selected['engineer']).'"','name="controlEngineerUserId" value="'.$e($selected['engineer']).'" checked',$body);}if($selected['confirmed']??false)$body=\str_replace('name="controlEngineerConfirmed" value="yes"','name="controlEngineerConfirmed" value="yes" checked',$body);$field=$f['flash']['field']??null;if(\in_array($field,['installers','engineer','confirmation'],true)){$errorId=$field.'-error';$body=\str_replace('role="status"','role="status" id="'.$errorId.'"',$body);$name=match($field){'installers'=>'installerTabIds[]','engineer'=>'controlEngineerUserId','confirmation'=>'controlEngineerConfirmed'};$body=\str_replace('name="'.$name.'"','name="'.$name.'" aria-describedby="'.$errorId.'"',$body);}
        return PilotView::document($user,'Состав распоряжения','Объекты монтажа',PilotView::breadcrumb([['Объекты монтажа','/pilot/objects'],['Объект монтажа № '.$id,'/pilot/objects/'.$id]],'Состав распоряжения'),$body);
    }
    public function renderCompatibility(HttpUser $user,array $f):string
    {
        $id=PilotView::e($f['id']);$shared=$this->render($user,$f);$start=\strpos($shared,'<main class="fm2-main" id="main-content" tabindex="-1">');$end=\strrpos($shared,'</main>');if($start===false||$end===false)throw new \LogicException();$start=\strpos($shared,'>',$start)+1;$navEnd=\strpos($shared,'</nav>',$start);if($navEnd!==false)$start=$navEnd+6;$body=\substr($shared,$start,$end-$start);return '<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Состав распоряжения — FMonitor 2.0</title><link rel="stylesheet" href="/pilot/assets/shlz.css"></head><body class="shlz-scope"><a class="shlz-link" href="#main-content">Перейти к содержанию</a><header><strong>FMonitor 2.0</strong><span>'.PilotView::e($user->displayName).'</span></header><nav aria-label="Хлебные крошки"><a class="shlz-link" href="/pilot/objects">Объекты монтажа</a><a class="shlz-link" href="/pilot/objects/'.$id.'">Объект монтажа № '.$id.'</a><span aria-current="page">Состав распоряжения</span></nav><main id="main-content" tabindex="-1">'.$body.'</main></body></html>';
    }
}
